css:
/* 复古印刷 · Riso Print
   纸浆颗粒、套印错位、网点、铅字压痕。黑墨 + 两个专色（朱红 / 钴蓝），
   所有面板像印在纸上的色块，边缘故意错半毫米。纯 CSS。 */

html[data-theme] {
  color-scheme: light;
  --bg: #f3ecdb;
  --ink: #17150f; --muted: #5c5546; --dim:#716959;
  --soft: #2a261d; --meta: #5c5546; --bright: #0d0b08;
  --line: #d8cdb4; --line2: #e6dcc7;
  --accent:#c92518; --accent2: #2f5bd6; --accentText: #fdf7ea;
  --good: #2f7d55; --warn: #c2761c;
  --glow1: rgba(230, 59, 46, 0.14); --glow2: rgba(47, 91, 214, 0.14);
  --panel: #f8f1e1; --panel2: #f3e9d3;
  --dock1: #faf4e6; --dock2: #f5ecd7;
  --glass: #f8f1e1;
  --track: #e3d8bf; --scroll: #b8ab8e; --coverbg: #ebe2cc;
  --menu: #faf4e6; --menu1: #fdf8ec; --menu2: #f3e9d3; --chev: #7d7460;
  --edge: #c9bca0; --edge2: #e63b2e;
  --hover: #f1e7d1; --tick: #d8cdb4;
  --inset: rgba(255, 255, 255, 0.34); --wordactive: #0d0b08; --swborder: #b8ab8e;
  --shadow-dock: 5px 6px 0 rgba(23, 21, 15, 0.18);
  --serif: "Iowan Old Style", "Palatino Linotype", Georgia, "Songti SC", "Noto Serif SC", serif;
  --bottom: 140px;
  --shell-nav: #efe3c9; --shell-nav2: #efe3c9;
  --shell-navin: #17150f; --shell-navmuted: #5c5546; --shell-navline: #c9bca0;
  --accent-ink:#c92518;}

html[data-theme] body {
  background:
    radial-gradient(rgba(23, 21, 15, 0.16) 0.7px, transparent 0.9px) 0 0 / 6px 6px,
    radial-gradient(800px 500px at 90% -10%, rgba(47, 91, 214, 0.1), transparent 64%),
    radial-gradient(700px 480px at 6% 4%, rgba(230, 59, 46, 0.09), transparent 62%),
    #f3ecdb;
}
/* 纸纹 + 极轻的套印错位感 */
html[data-theme] body::after {
  content: ""; position: fixed; inset: 0; pointer-events: none; z-index: 1; opacity: 0.55;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='200' height='200'><filter id='g'><feTurbulence type='fractalNoise' baseFrequency='0.75' numOctaves='3'/><feColorMatrix type='saturate' values='0'/></filter><rect width='100%25' height='100%25' filter='url(%23g)' opacity='0.25'/></svg>");
  mix-blend-mode: multiply;
}

/* 侧栏：一整块专色油墨 */
html[data-theme] .sidebar {
  margin: 12px 0 12px 12px; padding: 22px 14px;
  border: 2px solid #17150f; border-radius: 3px;
  background:
    linear-gradient(180deg, rgba(230, 59, 46, 0.12), transparent 26%),
    #efe3c9;
  box-shadow: 5px 6px 0 rgba(23, 21, 15, 0.2);
}
html[data-theme] .brand { padding: 0 8px 18px; border-bottom: 2px solid #17150f; margin-bottom: 14px; }
html[data-theme] .brand .brand-name, html[data-theme] .brand strong {
  font-family: var(--serif); font-size: 15px; letter-spacing: 0.12em; text-transform: uppercase;
}
html[data-theme] .nav button {
  border-radius: 0; border-bottom: 1px solid #d8cdb4; font-family: var(--serif); font-size: 12.5px; color: #5c5546;
}
html[data-theme] .nav button:hover { background: rgba(47, 91, 214, 0.08); color: #17150f; }
html[data-theme] .nav button.active {
  background: #e63b2e; color: #fdf7ea; box-shadow: 3px 3px 0 #2f5bd6;
}

/* 顶栏：印刷标题条 */
html[data-theme] .topbar {
  margin-top: 12px; padding: 0 16px; height: 62px; border: 2px solid #17150f; border-radius: 2px;
  background: #faf4e6; box-shadow: 4px 5px 0 rgba(23, 21, 15, 0.16);
}
html[data-theme] .search-global { border: 1px solid #17150f; border-radius: 0; background: #fdf8ec; }
html[data-theme] .icon-btn { border: 1px solid #17150f; border-radius: 0; background: #fdf8ec; }

/* 首页：铅字标题 + 错位色块 */
html[data-theme] .ledger-mast {
  margin-top: 22px; padding: 32px; border: 2px solid #17150f; border-radius: 2px;
  background:
    radial-gradient(rgba(23, 21, 15, 0.14) 1px, transparent 1.2px) 0 0 / 8px 8px,
    #f8f1e1;
  box-shadow: 6px 7px 0 rgba(230, 59, 46, 0.32), -4px -4px 0 rgba(47, 91, 214, 0.22);
}
html[data-theme] .ledger-mast h1, html[data-theme] .ledger-mast .mast-title {
  font-family: var(--serif); font-size: clamp(42px, 5.6vw, 78px); line-height: 1; letter-spacing: -1.6px;
  color: #17150f; text-shadow: 2px 2px 0 rgba(230, 59, 46, 0.34), -1px -1px 0 rgba(47, 91, 214, 0.28);
}
html[data-theme] .ledger-mast h1 em { color: #e63b2e; font-style: italic; }
html[data-theme] .ledger-mast p, html[data-theme] .subtitle { color: #5c5546; }

/* 卡片：纸上印块 */
html[data-theme] .card, html[data-theme] .pod-card, html[data-theme] .continue {
  border: 2px solid #17150f; border-radius: 2px; background: #f8f1e1;
  box-shadow: 4px 4px 0 rgba(47, 91, 214, 0.24), -3px -3px 0 rgba(230, 59, 46, 0.18);
}
html[data-theme] .pod-card:hover, html[data-theme] .continue:hover {
  transform: translate(-1px, -1px);
  box-shadow: 6px 6px 0 rgba(47, 91, 214, 0.3), -4px -4px 0 rgba(230, 59, 46, 0.24);
}
html[data-theme] .btn {
  border: 2px solid #17150f; border-radius: 0; background: #fdf8ec; color: #17150f;
  font-family: var(--serif); font-weight: 700; letter-spacing: 0.04em;
  box-shadow: 3px 3px 0 rgba(23, 21, 15, 0.22);
}
html[data-theme] .btn.primary { background: #e63b2e; color: #fdf7ea; border-color: #17150f; }
html[data-theme] .btn:active { transform: translate(2px, 2px); box-shadow: 1px 1px 0 rgba(23, 21, 15, 0.22); }

/* 统计：错版图表 */
html[data-theme] #page-stats .page-head {
  margin: 16px 0; padding: 26px 28px; border: 2px solid #17150f; border-radius: 2px;
  background: #f3e9d3; box-shadow: 6px 6px 0 rgba(47, 91, 214, 0.26), -4px -4px 0 rgba(230, 59, 46, 0.16);
}
html[data-theme] #page-stats .page-head h1 {
  font-family: var(--serif); font-size: clamp(32px, 4.6vw, 56px); letter-spacing: -1.6px; color: #17150f;
  text-shadow: 2px 2px 0 rgba(230, 59, 46, 0.3);
}
html[data-theme] #page-stats .eyebrow { color: var(--accent-ink); letter-spacing: 0.24em; }
html[data-theme] #page-stats .stat {
  border: 2px solid #17150f; border-radius: 2px; padding: 20px 22px;
  background: #f8f1e1; box-shadow: 3px 3px 0 rgba(23, 21, 15, 0.2);
}
html[data-theme] #statsCards .stat:nth-child(1) { background: #fde3dd; }
html[data-theme] #statsCards .stat:nth-child(2) { background: #e0e7fb; }
html[data-theme] #statsCards .stat:nth-child(3) { background: #f7eed2; }
html[data-theme] #page-stats .stat:before { content: none; }
html[data-theme] #page-stats .stat strong {
  font-family: var(--serif); font-size: 34px; font-weight: 700; color: #17150f;
  background: none; -webkit-text-fill-color: #17150f; text-shadow: 1px 1px 0 rgba(230, 59, 46, 0.28);
}
html[data-theme] #page-stats .stat label, html[data-theme] #page-stats .stat em { color: #5c5546; }
html[data-theme] #page-stats .card { border-radius: 2px; }
html[data-theme] #page-stats .stat-bar { border-radius: 0; border-bottom: 1px solid #d8cdb4; background: transparent; }
html[data-theme] #page-stats .stat-track { height: 9px; border-radius: 0; background: repeating-linear-gradient(90deg, #e6dcc7 0 3px, #f3ecdb 3px 6px); box-shadow: none; }
html[data-theme] #page-stats .stat-track i { border-radius: 0; background: repeating-linear-gradient(90deg, #e63b2e 0 5px, #f07a6c 5px 9px); box-shadow: none; }
html[data-theme] #page-stats .stats-year-head {
  margin-top: 26px; padding: 26px 28px; border: 2px solid #17150f; border-radius: 2px;
  background: #e0e7fb; box-shadow: 6px 6px 0 rgba(230, 59, 46, 0.24);
}
html[data-theme] #page-stats .year-title { font-family: var(--serif); font-size: 44px; color: #17150f; background: none; -webkit-text-fill-color: #17150f; text-shadow: 2px 2px 0 rgba(47, 91, 214, 0.3); }
html[data-theme] #page-stats #echoYear { border: 2px solid #17150f; border-radius: 0; background: #faf4e6; color: #17150f; font-family: var(--serif); }

/* 设置 */
html[data-theme] .ct-box { border: 2px solid #17150f; border-radius: 2px; background: #f8f1e1; }
html[data-theme] .ct-code, html[data-theme] #ctCss, html[data-theme] #ctHtml {
  border: 1px solid #17150f; border-radius: 0; background: #fdf8ec; color: #17150f;
}

/* 播放舱 */
@media (min-width: 901px) {
  html[data-theme] body .dock {
    left: 50%; right: auto; bottom: 18px; translate: -50% 0;
    width: min(880px, calc(100vw - 40px)); max-width: calc(100vw - 24px);
    padding: 14px 24px 16px; border: 2px solid #17150f; border-radius: 2px;
    background: #faf4e6; box-shadow: 5px 6px 0 rgba(23, 21, 15, 0.2), 8px 9px 0 rgba(47, 91, 214, 0.14);
  }
  html[data-theme] .mini-player { left: 292px; }
}
html[data-theme] .dock .playbtn { border: 2px solid #17150f; border-radius: 0; background: #e63b2e; color: #fdf7ea; box-shadow: 2px 2px 0 rgba(23, 21, 15, 0.24); }
html[data-theme] .mini-player { border: 2px solid #17150f; border-radius: 0; background: #faf4e6; box-shadow: 4px 4px 0 rgba(23, 21, 15, 0.18); }

html[data-theme] .cue.active .word { color: #0d0b08; background: #f9d9d2; box-shadow: 0 2px 0 #e63b2e; }
html[data-theme] ::-webkit-scrollbar-thumb { background: #b8ab8e; border-radius: 0; }

/* ---------- 12. 壁纸模式：全屏字幕层 ---------- */
html[data-theme] .wallpaper { background: #f3ecdb; color: #17150f; }
html[data-theme] .wp-bg { filter: blur(30px) sepia(.35) saturate(120%) brightness(1.3); opacity: .3; }
html[data-theme] .wp-shade { background: linear-gradient(90deg, rgba(243,236,219,.95) 0%, rgba(243,236,219,.86) 50%, rgba(243,233,211,.78) 78%, rgba(243,236,219,.95) 100%); }
html[data-theme] .wp-kicker { color: #2f5bd6; font-weight:700;letter-spacing:.22em;text-transform:uppercase; }
html[data-theme] .wp-title { color: #17150f; font-weight:700;letter-spacing:-.02em; }
html[data-theme] .wp-cue.past, html[data-theme] .wp-cue.future { color: rgba(23,21,15,.7); }
html[data-theme] .wp-cue.active::before { background: #e63b2e; box-shadow: 3px 0 0 rgba(47,91,214,.55); width:clamp(4px,.32vw,6px);border-radius:0; }
html[data-theme] .wp-cue.active .wp-en { color: #17150f; text-shadow: 2px 1px 0 rgba(230,59,46,.22), -2px -1px 0 rgba(47,91,214,.22); font-weight:700; }
html[data-theme] .wp-word.past { color: #17150f; }
html[data-theme] .wp-word.active { color: #17150f; background-image: linear-gradient(180deg, transparent 58%, rgba(230,59,46,.4) 58%, rgba(230,59,46,.4) 90%, rgba(47,91,214,.35) 90%, rgba(47,91,214,.35) 94%, transparent 94%); text-shadow: none; border-radius:0; }
html[data-theme] .wp-zh { color: rgba(23,21,15,.6); font-weight:400; }
html[data-theme] .wp-label { color: rgba(23,21,15,.4); }
html[data-theme] .wpbtn { background: #f8f1e1; border-color: #d8cdb4; color: #17150f; border-radius:2px;box-shadow:2px 2px 0 rgba(23,21,15,.16);font-weight:600;letter-spacing:.04em; }
html[data-theme] .wpbtn:hover { background: #e63b2e; border-color: #e63b2e; color: #fdf7ea; }
html[data-theme] .wp-shade::after { background-image: radial-gradient(rgba(23,21,15,.12) .6px, transparent .6px); background-size: 3px 3px; opacity:.6; }

/* ---------- 13. 底栏几何：与内置对齐 ---------- */
html[data-theme] body .dock {
  left: 50% !important; right: auto !important; translate: -50% 0 !important; bottom: 16px !important;
  width: min(1040px, calc(100% - 40px)) !important; max-width: none !important; margin: 0 !important;
}
html[data-theme] body.player-open .dock {
  left: 0 !important; right: 0 !important; translate: none !important; bottom: 16px !important;
  width: auto !important; max-width: min(880px, calc(100vw - 40px)) !important; margin: 0 auto !important;
}
html[data-theme] .mini-player { left: 258px; right: 20px; }
@media (max-width: 1180px) { html[data-theme] .mini-player { left: 220px; } }
@media (max-width: 900px) { html[data-theme] .mini-player { left: 10px; right: 10px; bottom: 64px; } }
html[data-theme] body.nav-collapsed .mini-player { left: 20px; right: 20px; }

/* ---------- 14. 播放工具面板（更多）：按主题重绘 ---------- */

html[data-theme] .docksheet { border-radius: 2px; border: 2px solid #17150f; background: #f7efdd; box-shadow: 5px 5px 0 rgba(23,21,15,.22); }
html[data-theme] .dshead { border-bottom: 1.5px solid #17150f; }
html[data-theme] .dstile { background: #f8f1e1; border: 1.5px solid #17150f; border-radius: 2px; color: #17150f; font-weight: 600; box-shadow: 3px 3px 0 rgba(47,91,214,.2); }
html[data-theme] .dstile:hover { background: #fffaf0; border-color: #e63b2e; box-shadow: 3px 3px 0 rgba(230,59,46,.35); }
html[data-theme] .dstile[aria-pressed="true"], html[data-theme] .dstile[aria-expanded="true"] { background: #e63b2e; color: #fdf7ea; border-color: #e63b2e; box-shadow: 3px 3px 0 rgba(47,91,214,.4); }
html[data-theme] .dspill { border-radius: 2px; border: 1.5px solid #17150f; background: #f8f1e1; color: #17150f; font-weight: 600; }
html[data-theme] .dsmute { border-radius: 2px; border: 1.5px solid #17150f; }
html[data-theme] .dsrange::-webkit-slider-thumb { -webkit-appearance: none; width: 14px; height: 14px; border-radius: 2px; background: #e63b2e; box-shadow: 2px 2px 0 #2f5bd6; }

/* ---------- 可访问性收尾（2026-11-21，与液态玻璃同一套标准） ---------- */
/* 列表里的时长/时间点用等宽数字，12:04 与 1:02:04 的冒号能竖着对齐 */
html[data-theme] :where(.ep-dur, .dur, .time, .clock, .dst-time, .wp-time) {
  font-variant-numeric: tabular-nums;
}
/* 大标题与副标题防孤字 */
html[data-theme] :where(.page-head h1, .ledger-mast h1, .year-title, .page-head .subtitle) {
  text-wrap: balance;
}
/* 按下态这套主题本来就有（2px 位移 + 硬阴影），这里不再追加 translateY，免得叠成双重位移。 */
/* 选中文字跟随主题强调色，别用系统蓝 */
html[data-theme] ::selection {
  background: color-mix(in srgb, var(--accent) 26%, transparent);
}
/* 基础样式已有全局 2px 焦点描边，这里只把圈收进来一点，避免被圆角切掉 */
html[data-theme] :where(button, [role="button"], [role="tab"], a[href]):focus-visible {
  outline-offset: 1px;
}
/* 尊重系统「减少动态效果」：漂移/闪烁/位移都是纯装饰，状态变化靠颜色与描边表达 */
@media (prefers-reduced-motion: reduce) {
  html[data-theme] *, html[data-theme] *::before, html[data-theme] *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
  html[data-theme] :where(.nav button, .pod-card, .continue, .stat, .dstile,
    .theme-card, .custom-card, .ep-row, .swatch):hover {
    transform: none !important;
  }
}

/* 首页卡片内衬：底座把 .ledger-home .pod-card 的内距清零、封面出血；本主题给卡片描边后
   必须自己把字与按钮推回内衬里，否则贴边框；并让四张卡按钮同基线 */
html[data-theme] .ledger-home .pod-card { padding: 0 0 14px; overflow: hidden; }
html[data-theme] .ledger-home .pod-card .pod-card-main { flex: 1 1 auto; }
html[data-theme] .ledger-home .pod-card .pod-card-main > :not(.pod-art) { margin-left: 14px; margin-right: 14px; }
html[data-theme] .ledger-home .pod-card .pod-actions { margin: 12px 14px 0; }
